INSERT INTO `invest_settings` VALUES ('0d47e35a-b803-4056-9cb3-adcfae71a294','hero','{\"title\": \"Invest in the next chapter of Dynime Technologies\", \"eyebrow\": \"Dynime Technologies Limited\", \"subtitle\": \"Back a profitable, remote-first digital studio shipping web, eCommerce, marketing and SaaS products to clients across 25+ countries. Transparent tiers. Real monthly payouts. Principal returned at end of cycle.\", \"trust_line\": \"Registered company · Bank-verified payouts · Signed agreement on every investment\", \"primary_cta\": \"View plans\", \"secondary_cta\": \"Open investor portal\"}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('3d0ae691-6512-4697-b081-af0a037bb502','shares','{\"note\": \"Each share = $100. Profit share = (your shares / total shares) × company profit × profit pool %.\", \"currency\": \"USD\", \"min_shares\": 1, \"share_price\": 100, \"shares_sold\": 0, \"total_shares\": 500, \"payout_frequency\": \"monthly\", \"profit_pool_percent\": 40, \"max_shares_per_investor\": 100, \"projected_annual_profit\": 120000}','2026-05-16 10:23:52','2026-05-16 10:23:52'),('67343556-cf13-4832-919b-bf122a072d6f','policy','{\"html\": \"<p>Capital is invested via bank transfer to the Dynime Technologies Limited company account. Returns and the original principal are paid back to your verified bank account at the end of each period. We reserve the right to cancel any partnership at any time if it conflicts with our terms and conditions, including those related to partnership agreements and capital gain systems.</p>\"}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('6a90e70c-b91f-4645-b7f5-3c6d8d7378be','targets','{\"items\": [{\"name\": \"Dynime Technologies\", \"slug\": \"dynime-technologies\", \"enabled\": true, \"description\": \"Our flagship digital agency: web, eCommerce, marketing & consulting services.\", \"roi_multiplier\": 1, \"profit_share_multiplier\": 1}, {\"name\": \"Dynime OS\", \"slug\": \"dynime-os\", \"enabled\": true, \"description\": \"Our SaaS business management platform for agencies and SMBs.\", \"roi_multiplier\": 1.15, \"profit_share_multiplier\": 1.2}, {\"name\": \"Upcoming Product (Market Research)\", \"slug\": \"upcoming-product\", \"enabled\": true, \"description\": \"Early-stage product backed by ongoing market research. Higher upside, longer horizon.\", \"roi_multiplier\": 1.35, \"profit_share_multiplier\": 1.5}]}','2026-05-16 08:36:14','2026-05-16 08:36:14'),('8224d3d7-8229-439e-bfd9-9a760d2ebddb','portal','{\"url\": \"/investor-portal\", \"label\": \"Investor Portal\", \"description\": \"Sign agreements, view statements, request withdrawals.\"}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('8ba9a1b4-99ef-41a6-8c3f-7fec233b8382','rules','{\"kyc_required\": true, \"support_email\": \"investors@dynime.com\", \"min_withdrawal\": 100, \"supported_currencies\": [\"USD\", \"EUR\", \"GBP\", \"BDT\"], \"withdrawal_fee_percent\": 0}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('91eab452-95ab-46e1-b05d-a49949ccff34','fundraising','{\"phases\": [{\"name\": \"Phase 1\", \"items\": [\"Launch revenue-sharing system\", \"Build customer base\", \"Focus on recurring revenue\"]}, {\"name\": \"Phase 2\", \"items\": [\"Improve retention and scaling\", \"Increase monthly recurring revenue\", \"Build investor confidence\"]}, {\"name\": \"Phase 3\", \"items\": [\"Raise larger strategic funding\", \"Expand into bigger markets\", \"Improve company valuation\"]}], \"currency\": \"USD\", \"goal_uses\": [\"Expand Dynime OS\", \"Improve infrastructure\", \"Scale marketing\", \"Hire team members\", \"Increase recurring SaaS revenue\"], \"goal_title\": \"Raising $50,000 to scale Dynime\", \"goal_amount\": 50000, \"goal_subtitle\": \"Hybrid structure — revenue sharing for the public, annual profit share for members, limited equity for strategic partners.\", \"messaging_note\": \"We use \\\"performance-based revenue sharing linked to Dynime\'s business growth\\\" — never \\\"guaranteed returns\\\".\", \"return_targets\": [{\"risk\": \"Low Risk\", \"return\": \"8–10%\"}, {\"risk\": \"Medium Risk\", \"return\": \"10–15%\"}, {\"risk\": \"High Growth\", \"return\": \"15–20%\"}], \"equity_cap_note\": \"Dynime caps total early-stage equity at 10–12% to protect ownership and long-term value.\", \"equity_structure\": [{\"amount\": 5000, \"equity\": \"1%\"}, {\"amount\": 10000, \"equity\": \"2%\"}, {\"amount\": 25000, \"equity\": \"4–5%\"}, {\"amount\": 50000, \"equity\": \"8–10% MAX\"}], \"profit_allocation\": [{\"label\": \"Business Growth & Development\", \"percent\": 60}, {\"label\": \"Operational Reserve\", \"percent\": 20}, {\"label\": \"Investor Distribution\", \"percent\": 20}], \"investor_distribution\": [{\"label\": \"Small Investors\", \"amount\": 15000}, {\"label\": \"Medium Investors\", \"amount\": 20000}, {\"label\": \"Strategic Investors\", \"amount\": 15000}], \"monthly_revenue_allocation\": [{\"label\": \"Product Development\", \"percent\": 35}, {\"label\": \"Marketing\", \"percent\": 20}, {\"label\": \"Operations\", \"percent\": 20}, {\"label\": \"Investor Distribution\", \"percent\": 15}, {\"label\": \"Emergency Reserve\", \"percent\": 10}]}','2026-05-16 08:50:20','2026-05-16 08:50:20'),('9f486e9c-c220-4f74-af86-7b8226ec8f11','faq','{\"items\": [{\"a\": \"A registered digital agency providing web development, eCommerce, digital marketing, business consulting and global company formation, with clients across the USA, Europe and Asia.\", \"q\": \"Who is Dynime Technologies Limited?\"}, {\"a\": \"Returns are paid to your bank account at the end of each month. Biannual bonuses are added every 6 months. 100% of the principal is returned at the end of the 24-month cycle (12 months for the Profit Share Partnership).\", \"q\": \"How do payouts work?\"}, {\"a\": \"You partner on revenue: 30% on every web project, 20% on marketing retainers and 10% on consulting. We add your share to your sheet for each sale and pay out quarterly, with a +5% bonus every 12 months.\", \"q\": \"What is the Profit Share Partnership?\"}, {\"a\": \"Every investment is backed by a signed agreement generated from your investor portal, settled into our company bank account and tracked in your dashboard with itemised statements.\", \"q\": \"How is my investment protected?\"}, {\"a\": \"Withdrawals before the end of the cycle are reviewed case by case from the investor portal. Approved withdrawals are paid to your bank within 7–10 business days.\", \"q\": \"Can I cancel or withdraw early?\"}, {\"a\": \"Inside your investor portal under Agreements. You can re-download the signed PDF at any time.\", \"q\": \"Where is my agreement stored?\"}]}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('b4556bd2-fe1d-4c61-b597-e197251e30ba','benefits','{\"items\": [{\"body\": \"Returns wired to your bank every month, with bonuses every 6 months.\", \"icon\": \"trending-up\", \"title\": \"Real monthly payouts\"}, {\"body\": \"Every investment is backed by a signed agreement generated from your investor portal.\", \"icon\": \"shield\", \"title\": \"Signed agreement\"}, {\"body\": \"Track every payout, bonus and the projected principal-return date in your dashboard.\", \"icon\": \"file-text\", \"title\": \"Transparent statements\"}, {\"body\": \"Choose Tier 3 to earn a share of revenue on every web, marketing and consulting sale.\", \"icon\": \"users\", \"title\": \"Profit-share option\"}, {\"body\": \"At end of cycle, roll your principal into a higher tier without restarting paperwork.\", \"icon\": \"gift\", \"title\": \"Renew or upgrade\"}, {\"body\": \"Sign agreements, request withdrawals and download statements — all from one place.\", \"icon\": \"vote\", \"title\": \"Investor portal\"}]}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('ee8460cd-88c2-457a-9ccd-f7a3aeb0740f','calculator','{\"default_amount\": 10000, \"default_plan_slug\": \"growth\", \"compounding_options\": [\"none\", \"monthly\", \"quarterly\"], \"platform_fee_percent\": 0, \"default_duration_months\": 24}','2026-05-15 13:27:46','2026-05-15 13:27:46'),('f6f1ded6-203b-4fe1-88d1-c9863618c25b','stats','{\"items\": [{\"sub\": \"USA · Europe · Asia\", \"label\": \"Active client base\", \"value\": \"3 continents\"}, {\"sub\": \"depending on tier\", \"label\": \"Avg. monthly return\", \"value\": \"2.5–5%\"}, {\"sub\": \"end of cycle\", \"label\": \"Principal return\", \"value\": \"12–24 months\"}, {\"sub\": \"+ biannual bonus\", \"label\": \"Payout cadence\", \"value\": \"Monthly\"}]}','2026-05-15 13:27:46','2026-05-15 13:27:46');
