INSERT INTO `investment_plans` VALUES ('5ca094b3-43d7-44ed-ad18-4c59b5a0adb0','equity-partnership','Equity Partnership','Strategic investors — $10,000+','Limited equity partnership for strategic investors. Equity plus dividends, long-term growth.',10000.00,NULL,'USD',0.00,0.00,3650,'yearly','high','equity-partnership',NULL,0.00,'Equity is permanent and only offered to a limited number of strategic partners. Subject to founder approval and signed shareholder agreement.',NULL,'[\"Equity + dividends\", \"Long-term growth alignment\", \"$5K → ~1% · $10K → ~2% · $25K → 4–5% · $50K → 8–10% max\", \"Founders cap total early-stage equity at 10–12%\", \"Permanent partnership, signed shareholder agreement\"]',1,0,4,'2026-05-16 08:50:20','2026-05-16 08:50:20'),('846c9274-049c-4090-9371-93767574bbdb','growth','Annual Profit Share','Medium investors — $500–$10,000','Yearly distribution from company net profit. Renewable each year.',500.00,10000.00,'USD',12.00,0.00,365,'yearly','moderate','annual-profit-share',1000000.00,0.00,'24-month lock-in. Principal returned at end of cycle.','Tier 2 — Medium Investors. Monthly Return 3.5–5%. Biannual bonus +1%. Annual ROI 42–60%. Principal returned after 24 months.','[\"8–15% suggested annual return\", \"One distribution per year\", \"Renewable yearly\", \"No ownership dilution\", \"Priority on next-year allocation\"]',1,1,2,'2026-05-15 13:27:46','2026-05-16 08:50:20'),('c6005b33-f044-4130-99d0-30f58de45c47','profit-share','Fixed Monthly Return','Recurring income — $1,000–$10,000','Target monthly payout tied to recurring SaaS and services revenue.',1000.00,10000.00,'USD',17.00,0.00,1095,'monthly','moderate','fixed-monthly',500000.00,0.00,'12-month cycle. Principal returned at end of cycle.','Tier 3 — Profit Share Partnership. Web 30% / Marketing 20% / Consulting 10%. Quarterly bonus +5% every 12 months. Principal returned after 12 months.','[\"14–20% target annual return\", \"Monthly payout target\", \"1–3 year cycle\", \"Principal returned at end of cycle\", \"No equity given\"]',1,0,3,'2026-05-15 13:27:46','2026-05-16 08:50:20'),('e43c0611-ac07-4846-8ca7-33f1c1e6656b','starter','Revenue Sharing','Small investors — $500–$5,000','Performance-based revenue sharing linked to Dynime\'s business growth. Paid monthly or quarterly.',500.00,5000.00,'USD',12.00,0.00,730,'monthly','low','revenue-sharing',250000.00,0.00,'24-month lock-in. Principal returned at end of cycle.','Tier 1 — Small Investors. Monthly Return 2.5–3%. Biannual bonus +1%. Annual ROI 30–36%. Principal returned after 24 months.','[\"10–15% suggested annual return\", \"Monthly or quarterly profit share\", \"2–3 year cycle\", \"No equity given — you keep flexibility\", \"Renewable at end of cycle\"]',1,0,1,'2026-05-15 13:27:46','2026-05-16 08:50:20');
