INSERT INTO `pages` VALUES ('1481ab48-0730-4086-97b8-5a6b11744491','Contact','contact','[{\"id\": \"c1\", \"type\": \"hero\", \"props\": {\"align\": \"center\", \"bgImage\": \"\", \"heading\": \"Contact Us\", \"overlay\": true, \"subtext\": \"Get in touch with our team. We would love to hear from you.\", \"buttonUrl\": \"\", \"buttonText\": \"\"}}, {\"id\": \"c2\", \"type\": \"paragraph\", \"props\": {\"text\": \"Whether you have a question about our services, pricing, or anything else, our team is ready to answer all your questions. Reach out to us and we will get back to you as soon as possible.\", \"align\": \"center\", \"color\": \"\"}}, {\"id\": \"c3\", \"type\": \"cta\", \"props\": {\"align\": \"center\", \"bgColor\": \"primary\", \"heading\": \"Ready to Start?\", \"subtext\": \"Fill out the form or reach us directly via email or phone.\", \"buttonUrl\": \"#contact-form\", \"buttonText\": \"Send Message\"}}]','Contact Dynime — Get in Touch','Get in touch with the Dynime team. We would love to hear from you and answer your questions.',NULL,1,'2026-04-24 13:40:14','2026-04-24 13:40:14'),('2cee7004-a43a-4ff2-ba98-48418c16022d','Services','services','[{\"id\": \"s1\", \"type\": \"hero\", \"props\": {\"align\": \"center\", \"bgImage\": \"\", \"heading\": \"Our Services\", \"overlay\": true, \"subtext\": \"Comprehensive digital solutions tailored to your business needs.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Contact Us\"}}, {\"id\": \"s2\", \"type\": \"features\", \"props\": {\"items\": [{\"icon\": \"Globe\", \"title\": \"Custom Websites\", \"description\": \"Responsive, fast, and SEO-optimized websites.\"}, {\"icon\": \"ShoppingCart\", \"title\": \"E-Commerce\", \"description\": \"Full-featured online stores with secure payments.\"}, {\"icon\": \"Code\", \"title\": \"Web Applications\", \"description\": \"Complex web apps with modern frameworks.\"}], \"columns\": 3, \"heading\": \"Web Development Services\"}}, {\"id\": \"s3\", \"type\": \"features\", \"props\": {\"items\": [{\"icon\": \"Search\", \"title\": \"SEO Optimization\", \"description\": \"Rank higher on search engines organically.\"}, {\"icon\": \"Share2\", \"title\": \"Social Media\", \"description\": \"Engaging social media campaigns.\"}, {\"icon\": \"FileText\", \"title\": \"Content Strategy\", \"description\": \"Compelling content that converts.\"}], \"columns\": 3, \"heading\": \"Digital Marketing\"}}, {\"id\": \"s4\", \"type\": \"cta\", \"props\": {\"align\": \"center\", \"bgColor\": \"primary\", \"heading\": \"Need a Custom Solution?\", \"subtext\": \"Let us discuss how we can help your business grow.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Request a Quote\"}}]','Our Services — Web, Marketing & Cloud','Comprehensive digital solutions tailored to your business needs: web development, e-commerce, marketing, and more.',NULL,1,'2026-04-24 13:40:14','2026-04-24 13:40:14'),('65564dd7-dec2-40d9-9f4c-f364aca08bb6','Home','home','[{\"id\": \"h1\", \"type\": \"hero\", \"props\": {\"align\": \"center\", \"bgImage\": \"\", \"heading\": \"Welcome to Dynime\", \"overlay\": true, \"subtext\": \"We build amazing digital experiences that drive growth and innovation.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Get Started\"}}, {\"id\": \"h2\", \"type\": \"features\", \"props\": {\"items\": [{\"icon\": \"Globe\", \"title\": \"Web Development\", \"description\": \"Custom websites and web applications built with modern technologies.\"}, {\"icon\": \"Megaphone\", \"title\": \"Digital Marketing\", \"description\": \"Strategic digital marketing campaigns that drive results.\"}, {\"icon\": \"Cloud\", \"title\": \"Cloud Solutions\", \"description\": \"Scalable cloud infrastructure and DevOps services.\"}], \"columns\": 3, \"heading\": \"Our Services\"}}, {\"id\": \"h3\", \"type\": \"testimonial\", \"props\": {\"role\": \"CEO\", \"quote\": \"Dynime transformed our digital presence completely. Their team delivered beyond expectations.\", \"author\": \"Happy Client\", \"avatar\": \"\"}}, {\"id\": \"h4\", \"type\": \"cta\", \"props\": {\"align\": \"center\", \"bgColor\": \"primary\", \"heading\": \"Ready to Get Started?\", \"subtext\": \"Contact us today for a free consultation and let us help you grow.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Contact Us\"}}]','Dynime — Digital Experiences That Convert','Full-service digital agency specializing in web development, e-commerce, digital marketing, and business formation.',NULL,1,'2026-04-24 13:40:14','2026-04-24 13:40:14'),('82fe0948-7f46-4dc9-b2d7-f8affc3b7182','Portfolio','portfolio','[{\"id\": \"p1\", \"type\": \"hero\", \"props\": {\"align\": \"center\", \"bgImage\": \"\", \"heading\": \"Our Portfolio\", \"overlay\": true, \"subtext\": \"Explore our latest projects and success stories.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Contact Us\"}}, {\"id\": \"p2\", \"type\": \"paragraph\", \"props\": {\"text\": \"We take pride in every project we deliver. Browse through our portfolio to see the diverse range of work we have done for clients across various industries.\", \"align\": \"center\", \"color\": \"\"}}, {\"id\": \"p3\", \"type\": \"cta\", \"props\": {\"align\": \"center\", \"bgColor\": \"primary\", \"heading\": \"Have a Project in Mind?\", \"subtext\": \"Let us bring your vision to life with our expertise.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Start a Project\"}}]','Our Portfolio — Recent Work & Case Studies','Explore our latest projects and success stories across web development, e-commerce, and digital marketing.',NULL,1,'2026-04-24 13:40:14','2026-04-24 13:40:14'),('f206a296-5186-48d8-a2b6-682a3c96d1c2','Blog','blog','[{\"id\": \"b1\", \"type\": \"hero\", \"props\": {\"align\": \"center\", \"bgImage\": \"\", \"heading\": \"Our Blog\", \"overlay\": true, \"subtext\": \"Insights, tips, and updates from the Dynime team.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Contact Us\"}}, {\"id\": \"b2\", \"type\": \"paragraph\", \"props\": {\"text\": \"Stay updated with the latest trends in web development, digital marketing, and technology. Our team shares valuable insights to help you make informed decisions for your business.\", \"align\": \"center\", \"color\": \"\"}}]','Blog — Insights from the Dynime Team','Insights, tips, and updates on web development, digital marketing, and technology from the Dynime team.',NULL,1,'2026-04-24 13:40:14','2026-04-24 13:40:14'),('fd8cb0d2-376e-47af-9fe4-a34c8551e8c6','About','about','[{\"id\": \"a1\", \"type\": \"hero\", \"props\": {\"align\": \"center\", \"bgImage\": \"\", \"heading\": \"About Dynime\", \"overlay\": true, \"subtext\": \"Learn about our journey, mission, and the team behind the innovation.\", \"buttonUrl\": \"/services\", \"buttonText\": \"Our Services\"}}, {\"id\": \"a2\", \"type\": \"paragraph\", \"props\": {\"text\": \"Dynime is a forward-thinking digital agency dedicated to helping businesses thrive in the digital age. Founded with a vision to bridge the gap between technology and business growth, we have been delivering innovative solutions to clients across the globe.\", \"align\": \"left\", \"color\": \"\"}}, {\"id\": \"a3\", \"type\": \"features\", \"props\": {\"items\": [{\"icon\": \"Users\", \"title\": \"Expert Team\", \"description\": \"Our team of skilled professionals brings years of experience.\"}, {\"icon\": \"Zap\", \"title\": \"Innovation First\", \"description\": \"We stay ahead with cutting-edge technologies and approaches.\"}, {\"icon\": \"Globe\", \"title\": \"Global Reach\", \"description\": \"Serving clients across multiple countries and industries.\"}], \"columns\": 3, \"heading\": \"Why Choose Us\"}}, {\"id\": \"a4\", \"type\": \"quote\", \"props\": {\"text\": \"Our mission is to empower businesses with innovative digital solutions that drive measurable results.\", \"color\": \"\", \"author\": \"Dynime Team\"}}, {\"id\": \"a5\", \"type\": \"cta\", \"props\": {\"align\": \"center\", \"bgColor\": \"primary\", \"heading\": \"Want to Work With Us?\", \"subtext\": \"Join our growing list of satisfied clients worldwide.\", \"buttonUrl\": \"/contact\", \"buttonText\": \"Get In Touch\"}}]','About Dynime — Our Story & Mission','Learn about Dynime, our journey, mission, and the team behind the innovation.',NULL,1,'2026-04-24 13:40:14','2026-04-24 13:40:14');
