INSERT INTO `products` VALUES ('010474cb-cb02-4587-92f3-cd7f568e4d38','WordPress Web Design','wordpress-design','Custom, responsive WordPress websites tailored to your brand. SEO-optimized, fast loading, mobile-first design that converts visitors into customers.',899.000000,'Web Development','https://images.unsplash.com/photo-1547658719-da2b51169166?w=1600&q=80&auto=format&fit=crop',1,1,1,NULL,NULL,'2026-04-24 15:25:15','2026-04-24 15:44:39'),('0a147187-dbfa-4b3f-a9b0-9d0e62cf5e93','Landing Page Template','landing-page-template','High-converting landing page template. Fully responsive, SEO-optimized, ready to customize and deploy.',49.000000,'Templates','https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?w=1600&q=80&auto=format&fit=crop',1,0,24,NULL,NULL,'2026-04-24 15:25:15','2026-04-24 15:44:39'),('1f4da20d-e260-4e68-92e9-dfdcb87edfdc','Website Redesign','website-redesign','Transform your outdated website into a modern, fast, conversion-optimized site. SEO-preserved migration with 301 redirects.',1299.000000,'Web Development','https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?w=1600&q=80&auto=format&fit=crop',1,1,2,NULL,NULL,'2026-04-24 15:25:15','2026-04-24 15:44:39'),('22b408da-d2ce-4d13-8613-54bb05d77b1e','UI/UX Design','ui-ux-design','User-centered design that converts. Wireframes, prototypes, and high-fidelity designs in Figma for web and mobile apps.',799.000000,'Web Development','https://images.unsplash.com/photo-1559028012-481c04fa702d?w=1600&q=80&auto=format&fit=crop',1,0,7,NULL,NULL,'2026-04-24 15:25:15','2026-04-24 15:44:39'),('2b73ce11-9549-446d-b1e4-6644d582c152','SEO Services','seo','Rank higher on Google with technical SEO, on-page optimization, content strategy, and authority link building.',799.000000,'SEO & Analytics','https://images.unsplash.com/photo-1571171637578-41bc2dd41cd2?w=1600&q=80&auto=format&fit=crop',1,1,12,NULL,NULL,'2026-04-24 15:25:15','2026-04-24 15:44:39'),('5247eb35-9503-4d1b-9260-e6ec70d808fa','Payment Gate