INSERT INTO `service_pricing` VALUES ('05261a8d-ac36-4cd4-bc0c-916c99f571d4','uk-company','UK Company Formation',1,'[{\"id\": \"uk-company-tier-m1sdzsmf\", \"name\": \"Starter\", \"period\": \"one-time\", \"cta_type\": \"fixed\", \"features\": [\"Ltd company incorporation\", \"Companies House filing fee included\", \"Digital certificate of incorporation\", \"Memorandum & Articles of Association\", \"Share certificate template\"], \"cta_label\": \"Start Small\", \"price_bdt\": 9900, \"price_usd\": 349, \"description\": \"Basic UK Ltd formation with Companies House filing\", \"highlighted\": false}, {\"id\": \"uk-company-tier-3rnan87c\", \"name\": \"Basic\", \"period\": \"one-time\", \"cta_type\": \"fixed\", \"features\": [\"Everything in Starter\", \"UK registered office (1 year)\", \"Director service address (1 year)\", \"VAT registration guidance\", \"Bank intro (Wise / Revolut Business)\"], \"cta_label\": \"Choose Basic\", \"price_bdt\": 19900, \"price_usd\": 499, \"description\": \"Non-resident friendly Ltd with UK address\", \"highlighted\": false}, {\"id\": \"uk-company-tier-if4goo4o\", \"name\": \"Professional\", \"period\": \"one-time + 30-day support\", \"cta_type\": \"fixed\", \"features\": [\"Everything in Basic\", \"VAT registration filed for you\", \"Confirmation Statement (1 filing)\", \"Bookkeeping starter setup\", \"Stripe / PayPal UK setup help\", \"30-day post-formation support\"], \"cta_label\": \"Most Popular\", \"price_bdt\": 39900, \"price_usd\": 599, \"description\": \"Best value — Ltd + address + VAT + first-year filings\", \"highlighted\": true}, {\"id\": \"uk-company-tier-lu02ufwx\", \"name\": \"Premium\", \"period\": \"one-time + 90-day care\", \"cta_type\": \"fixed\", \"features\": [\"Everything in Professional\", \"Annual accounts prep (small co.)\", \"Corporation tax return (CT600)\", \"PAYE registration\", \"Quarterly compliance reminders\", \"90-day post-formation care\"], \"cta_label\": \"Go Premium\", \"price_bdt\": 79900, \"price_us